const fs = require('fs');
const path = require('path');
const brainDir = 'C:\\Users\\mario\\.gemini\\antigravity\\brain';

function findSubscreenSecurity(dir) {
  const files = fs.readdirSync(dir);
  for (const f of files) {
    const full = path.join(dir, f);
    const stat = fs.statSync(full);
    if (stat.isDirectory()) findSubscreenSecurity(full);
    else if (f === 'transcript_full.jsonl') {
      const lines = fs.readFileSync(full, 'utf8').split('\n');
      lines.forEach((line, idx) => {
        if (line.includes('subscreen-security')) {
          console.log('Found in', full, 'line', idx + 1, 'length', line.length);
          fs.writeFileSync('scratch/found_security_' + Date.now() + '.json', line, 'utf8');
        }
      });
    }
  }
}
findSubscreenSecurity(brainDir);
